// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SyncAllowList Sync the allow list
	// (PUT /host/allow-list)
	SyncAllowList(ctx context.Context, request SyncAllowListRequestObject) (SyncAllowListResponseObject, error)
	// PullAuditRecords Pull audit records
	// (GET /host/audit)
	PullAuditRecords(ctx context.Context, request PullAuditRecordsRequestObject) (PullAuditRecordsResponseObject, error)
	// AckAuditRecords Acknowledge audit records
	// (POST /host/audit/ack)
	AckAuditRecords(ctx context.Context, request AckAuditRecordsRequestObject) (AckAuditRecordsResponseObject, error)
	// PushBudgetState Push budget state
	// (PUT /host/budget)
	PushBudgetState(ctx context.Context, request PushBudgetStateRequestObject) (PushBudgetStateResponseObject, error)
	// ListFreezes List active freezes
	// (GET /host/freezes)
	ListFreezes(ctx context.Context, request ListFreezesRequestObject) (ListFreezesResponseObject, error)
	// ApplyFreeze Freeze all, a team or an agent
	// (POST /host/freezes)
	ApplyFreeze(ctx context.Context, request ApplyFreezeRequestObject) (ApplyFreezeResponseObject, error)
	// SetGatewaySecret Set the gateway secret
	// (PUT /host/gateway-secret)
	SetGatewaySecret(ctx context.Context, request SetGatewaySecretRequestObject) (SetGatewaySecretResponseObject, error)
	// GetDoorHealth Door health
	// (GET /host/health)
	GetDoorHealth(ctx context.Context, request GetDoorHealthRequestObject) (GetDoorHealthResponseObject, error)
	// ReleaseFreeze Release a freeze
	// (POST /host/release)
	ReleaseFreeze(ctx context.Context, request ReleaseFreezeRequestObject) (ReleaseFreezeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

